set comp.annual_comp;
run;

* Find incidence of hopping;
proc sort data=comp nodupkey;
by execid year gvkey;
run;

proc sql;
create table hopping as select a.execid, a.year, a.gvkey, a.tdc1, a.ceoann, a.cfoann, a.coname, a.exec_fullname, b.gvkey as gvkey_new, b.year as year_new, b.tdc1 as tdc1_new, b.ceoann as ceoann_new, b.cfoann as cfoann_new, b.coname as coname_new
from comp as a, comp as b
where a.execid=b.execid and b.year-2<=a.year<=b.year and a.gvkey~=b.gvkey;

create table network1 as select distinct a.cik, a.year, a.louvain, a.louvain_small, a.disclose, b.gvkey, c.sale, c.mkvalt, c.sic, c.prcc_f, c.csho, c.at, c.state, c.ceq, (c.ib/c.at) as roa, c.datadate, c.lpermno, c.gsector
from network as a, link.cik_gvkey as b, fund.ccmfunda as c
where a.cik=input(b.cik, 12.) and year(b.FNDATE)<=a.year<=year(b.LNDATE) and a.year=c.fyear and b.gvkey=c.gvkey;

set crsp.msf;
if not(missing(ret));
year=year(date);
keep permno date year ret;

from network3 as a left join index.dow_nasdaq as b
on b.from<=a.datadate and (a.datadate<=b.thru or b.thru=.) and a.gvkey=b.gvkey and b.conm="Dow Jones Industrials-30 Stk";
quit;

proc sql;
create table network5 as select distinct a.*, b.permno as sp500
from network4 as a left join index.dsp500list as b
on b.start<=a.datadate<=b.ending and a.lpermno=b.permno;

proc sql;
create table segment as select distinct gvkey, datadate, sum(case when STYPE="BUSSEG" then 1 else 0 end) as bus_seg, sum(case when STYPE="GEOSEG" then 1 else 0 end) as geo_seg
from fund.segment
group by gvkey, datadate;

            DBMS=EXCEL REPLACE;
SHEET="Sheet1"; 
GETNAMES=YES;

create table hopping5 as select distinct a.*, b.fyear as flag1
from hopping4 as a left join peer as b
on a.year=b.fyear and (a.cik=b.cik_own and a.cik_new=b.cik_peer) ;

input year gvkey1$ gvkey2$ score;
format gvkey1 $6. gvkey2 $6. score 10.6;
informat gvkey1 $6. gvkey2 $6. score 10.6;
if gvkey1=gvkey2 then delete;

input year gvkey1$ gvkey2$ score;
format gvkey1 $6. gvkey2 $6. score 10.6;
informat gvkey1 $6. gvkey2 $6. score 10.6;
if gvkey1=gvkey2 then delete;

            DBMS=CSV REPLACE;
GETNAMES=YES;
RUN;

proc transpose data=ret_ff48 out=return_ff48 name=ff48 prefix=ret;
by date;
run;

create table analyst as select distinct a.*, b.gvkey
from ibes.analyst_detail as a, ibes.cibeslnk as b
where a.ticker=b.ticker and b.fdate<=a.anndats<=b.ldate;
quit;

data analyst;
set analyst;
if measure="EPS" and (FPI="6" or FPI="7");
year=year(anndats);

proc transpose data=wide_C_&year out=long_C_&year;
by ID;
run;

data long_C_&year;
set long_C_&year (rename=(ID=CIK_own _LABEL_=CIK_peer COL1=euclid_distance_C));
year=&year;
drop _NAME_;
run;

proc transpose data=wide_R_&year out=long_R_&year;
by ID;
run;

data long_R_&year;
set long_R_&year (rename=(ID=CIK_own _LABEL_=CIK_peer COL1=euclid_distance_R));
year=&year;
drop _NAME_;

%euclid(2006);
%euclid(2007);
%euclid(2008);
%euclid(2009);
%euclid(2010);
%euclid(2011);
%euclid(2012);
%euclid(2013);
%euclid(2014);
