create table hopping19 as select distinct a.*, b.tdc1 as tdc1_new
from hopping18 as a left join comp as b
on a.gvkey_new=b.gvkey and a.year=b.year;
quit;

proc sort data=hopping19 nodupkey;
by year gvkey gvkey_new;
run;

set crsp.msf;
if not(missing(ret));
year=year(date);
mkvalt=prc*shrout;
keep permno date year ret mkvalt prc shrout;

set comp.ccmfunda_0428;
sic2=floor(sic/100);
if mkvalt=. then mkvalt=prcc_f*csho;
roa=ib/at;
keep gvkey lpermno datadate fyear fyrc sic2 naics sale mkvalt roa at;

data comp;
set exec.Annual_comp;
if ceoann="CEO";
run;

data cpi;
set crsp.inflation;
run;

create table ret6 as select distinct a.*, b.gvkey, b.fyear, b.fyrc, b.sic2, c.cpiret
from ret5_win as a, funda as b, cpi as c
where a.year=year(c.caldt) and 0<=intck("month",b.datadate,a.date)<=11 and a.permno=b.lpermno and b.at>10;

data market;
set crsp.market;
run;

proc sql;
create table ret1 as select distinct a.*, b.gvkey, b.sic2, c.tdc1, c.co_per_rol, c.year as fyear, d.ewretd
from msf as a, funda as b, comp1 as c, market as d
where 0<=intck("month", a.date,b.datadate)<=11 and b.fyear=c.year and a.permno=b.lpermno and b.gvkey=c.gvkey and a.date=d.date;

data xtemp;
    set &dsetin;
    run;

%winsor(dsetin=ret1, dsetout=ret1_win, byvar=none, vars=ret, type=winsor, pctl=1 99);

proc sql;
create table ret2 as select distinct a.*, mean(a.ret) as ret_ind_ew
from ret1_win as a

input year gvkey1$ gvkey2$ score;
format gvkey1 $6. gvkey2 $6. score 10.6;
informat gvkey1 $6. gvkey2 $6. score 10.6;
if gvkey1=gvkey2 then delete;

create table rpe3 as select distinct a.*, b.idio_var, b.corr
from rpe2 as a full join control as b
on a.gvkey=b.gvkey and a.fyear=b.fyear;
quit;

proc sort data=rpe3 nodupkey;
by gvkey fyear;
run;

input year gvkey1$ gvkey2$ score;
format gvkey1 $6. gvkey2 $6. score 10.6;
informat gvkey1 $6. gvkey2 $6. score 10.6;
if gvkey1=gvkey2 then delete;

set comp.Annual_comp;
if ceoann="CEO";
keep gvkey year spcode execid exec_fullname becameceo joined_co leftco leftofc reason age salary bonus othann rstkgrnt option_awards_blk_value ltip allothtot tdc1;
