if gvkey1=gvkey2 then delete;

data fund;
set mylib1.funda;
run;

proc sort data=fund nodupkey;
by gvkey fyear;
run;

data fund;
set fund;
keep gvkey fyear sic sale state;
run;

            DBMS=EXCEL REPLACE;
SHEET="Sheet1"; 
GETNAMES=YES;

proc sql;
create table peer1 as select distinct a.*, b.gvkey as gvkey_own, c.tdc1 as tdc_own
from peer as a, link.cik_gvkey as b, comp as c
where a.cik_own=input(b.cik, 12.) and year(b.FNDATE)<=a.fyear<=year(b.LNDATE) and a.fyear=c.year and b.gvkey=c.gvkey;

            DBMS=EXCEL REPLACE;
SHEET="0616_1718"; 
GETNAMES=YES;

create table network1 as select distinct a.*, b.gvkey, c.tdc1, c.sale
from network as a, link.cik_gvkey as b, own_sic as c
where a.cik=input(b.cik, 12.) and year(b.FNDATE)<=a.year<=year(b.LNDATE) and a.year=c.year and b.gvkey=c.gvkey;

proc sort data=network1;
by year group_id descending tdc1;
run;

data tournament_final;
